import { getUtcDateKey, extractResonanceWords } from "@/lib/daily-questions"
import { createClient } from "@/lib/supabase/server"
import { NextResponse } from "next/server"

export const runtime = "edge"

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url)
  const anonymousId = searchParams.get("anonymousId")
  const questionDate = getUtcDateKey()

  if (!anonymousId) {
    return NextResponse.json({ error: "Anonymous ID is required" }, { status: 400 })
  }

  const supabase = await createClient()
  const { data: candidates, error } = await supabase
    .from("twin_intents")
    .select("id, anonymous_id, words, source_type, created_at")
    .eq("question_date", questionDate)
    .neq("anonymous_id", anonymousId)
    .gt("expires_at", new Date().toISOString())
    .order("created_at", { ascending: false })
    .limit(3)

  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  return NextResponse.json({ candidates: candidates || [], questionDate })
}

export async function POST(request: Request) {
  const body = await request.json()
  const anonymousId = String(body.anonymousId || "").trim()
  const sourceType = String(body.sourceType || "session")
  const sourceId = body.sourceId ? String(body.sourceId).trim() : null
  const textSeed = String(body.textSeed || body.emotion || "quiet present human").trim()

  if (!anonymousId) {
    return NextResponse.json({ error: "Anonymous ID is required" }, { status: 400 })
  }

  const supabase = await createClient()
  const questionDate = getUtcDateKey()

  const { data: intent, error } = await supabase
    .from("twin_intents")
    .upsert(
      {
        anonymous_id: anonymousId,
        source_type: sourceType,
        source_id: sourceId,
        question_date: questionDate,
        words: extractResonanceWords(textSeed),
        text_seed: textSeed,
        expires_at: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
      },
      { onConflict: "anonymous_id,question_date" }
    )
    .select()
    .single()

  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  return NextResponse.json({ intent })
}

